// Bundle the widget's front end (src/anywidget_graph/ui/index.js and the modules it imports) into the one ES module the
// widget loads: src/anywidget_graph/ui/dist/widget.js. Run after `npm ci` in this folder: npm run build:esm
// With --check it builds in memory and fails when the committed file differs (CI, and tests/test_ui.py).
import { build } from "esbuild";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const ui = join(here, "..", "..", "src", "anywidget_graph", "ui");
const out = join(ui, "dist", "widget.js");

const result = await build({
  entryPoints: [join(ui, "index.js")],
  // Inputs are named relative to this folder in the output's comments: the same file from wherever the script runs
  absWorkingDir: ui,
  bundle: true,
  format: "esm",
  // Readable output: a stack trace in a notebook points at code a person can follow
  minify: false,
  target: "es2022",
  charset: "utf8",
  legalComments: "none",
  write: false,
  logLevel: "warning",
  banner: { js: "// Generated by scripts/vendor/build-esm.mjs from src/anywidget_graph/ui: edit those, then npm run build:esm" },
});
const text = result.outputFiles[0].text;

if (process.argv.includes("--check")) {
  let committed = "";
  try {
    committed = readFileSync(out, "utf8").replaceAll("\r\n", "\n");
  } catch {
    // missing: stale
  }
  if (committed !== text) {
    console.error("src/anywidget_graph/ui/dist/widget.js is stale: run `npm run build:esm` in scripts/vendor");
    process.exit(1);
  }
  console.log("src/anywidget_graph/ui/dist/widget.js is up to date");
} else {
  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, text);
  console.log(`wrote ${out} (${text.length} bytes)`);
}
